function reverseBits(n) {
  let result = 0;
  for (let i = 0; i < 32; i++) {
    result = (result << 1) | (n & 1);   // place current lowest bit of n at result's lowest, then it gets shifted up next iter
    n >>>= 1;                           // unsigned right shift
  }
  return result >>> 0;                  // coerce to unsigned 32-bit
}
// Time O(32) = O(1), Space O(1)

